def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find the longest contiguous run of non-background cells as the pattern.
    best = []
    for row in grid:
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            if c - start > len(best):
                best = row[start:c]

    pattern_colors = set(best)
    triggers = [
        (r, c)
        for r in range(h)
        for c in range(w)
        if grid[r][c] != bg and grid[r][c] not in pattern_colors
    ]

    out = [row[:] for row in grid]
    offset = len(best) // 2
    for r, c in triggers:
        start = c - offset
        for i, color in enumerate(best):
            x = start + i
            if 0 <= x < w:
                out[r][x] = color
    return out
